use super::*;
use std::sync::Mutex;
struct F{dir:PathBuf,path:PathBuf,log:DispatchLog,identity:Value,cache:Mutex<ClosedRowsCache>}
impl Drop for F{fn drop(&mut self){let _=fs::remove_dir_all(&self.dir);}}
impl F{
 fn new()->Self{static NEXT:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);let dir=std::env::temp_dir().join(format!("closed-original-cache-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),NEXT.fetch_add(1,std::sync::atomic::Ordering::Relaxed)));fs::create_dir(&dir).unwrap();let path=dir.join("dispatch.ndjson");let log=DispatchLog::open(&path).unwrap();let identity=identity(&File::open(&path).unwrap()).unwrap();Self{dir,path,log,identity,cache:Default::default()}}
 fn closed(&mut self,id:u64,padding:usize){for e in [json!({"kind":"intent","qid":id,"original":"x".repeat(padding)}),json!({"kind":"attempt","qid":id}),json!({"kind":"ack","qid":id,"receipt":{"orderId":id+100}}),json!({"kind":"closed","qid":id})]{self.log.append(e).unwrap();}}
 fn read(&self,wanted:&[u64])->Result<(BTreeMap<u64,Vec<Value>>,FilePin)>{original_closed_rows(&self.cache,&self.path,&self.identity,&self.log,&wanted.iter().copied().collect())}
 fn parses(&self)->u64{self.cache.lock().unwrap().parses}
}
#[test]fn warm_cache_returns_exact_original_four_rows_and_fresh_held_pin(){let mut f=F::new();f.closed(1,0);let before=fs::read(&f.path).unwrap();let(a,p)=f.read(&[1]).unwrap();let(b,q)=f.read(&[1]).unwrap();assert_eq!(a,b);assert_eq!(a[&1].len(),4);assert_eq!(f.parses(),1);p.validate().unwrap();q.validate().unwrap();assert_eq!(fs::read(&f.path).unwrap(),before);assert_eq!(p.sha,q.sha);assert_eq!(q.identity,f.identity);}
#[test]fn different_wanted_sets_are_independent_and_live_membership_is_rechecked(){let mut f=F::new();f.closed(1,0);f.closed(2,0);assert_eq!(f.read(&[1]).unwrap().0.len(),1);assert_eq!(f.read(&[2]).unwrap().0.len(),1);assert_eq!(f.read(&[1,2]).unwrap().0.len(),2);f.read(&[1]).unwrap();assert_eq!(f.parses(),3);f.log.closed.remove(&1);assert!(f.read(&[1]).is_err());f.log.closed.insert(1);f.log.acknowledgments.remove(&1);assert!(f.read(&[1]).is_err());}
#[test]fn ordinary_append_invalidates_without_rejecting_legitimate_new_head(){let mut f=F::new();f.closed(1,0);let(first,old)=f.read(&[1]).unwrap();f.log.append(json!({"kind":"source","qid":900,"diagnostic":"normal append"})).unwrap();let(next,pin)=f.read(&[1]).unwrap();assert_eq!(first,next);assert_eq!(f.parses(),2);assert!(old.validate().is_err());pin.validate().unwrap();f.read(&[1]).unwrap();assert_eq!(f.parses(),2);}
#[test]fn warm_same_length_prefix_edit_never_returns_cached_rows(){let mut f=F::new();f.closed(1,20);f.read(&[1]).unwrap();let mut raw=fs::read(&f.path).unwrap();let i=raw.iter().position(|b|*b==b'x').unwrap();raw[i]=b'y';fs::write(&f.path,raw).unwrap();assert!(f.read(&[1]).is_err());assert_eq!(f.parses(),1);}
#[test]fn replacement_truncation_and_symlink_are_rejected_instead_of_cache_rescue(){for kind in 0..3{let mut f=F::new();f.closed(1,0);f.read(&[1]).unwrap();match kind{0=>{let original=f.path.with_extension("original");fs::rename(&f.path,&original).unwrap();fs::copy(original,&f.path).unwrap();},1=>{OpenOptions::new().write(true).open(&f.path).unwrap().set_len(10).unwrap();},_=>{let original=f.path.with_extension("original");fs::rename(&f.path,&original).unwrap();std::os::unix::fs::symlink(original,&f.path).unwrap();}}assert!(f.read(&[1]).is_err(),"kind {kind}");}}
#[test]fn cache_entry_count_and_total_serialized_bytes_are_bounded(){let mut f=F::new();for i in 1..=33{f.closed(i,0);}for i in 1..=33{f.read(&[i]).unwrap();let cache=f.cache.lock().unwrap();assert!(cache.entries.len()<=CLOSED_CACHE_COUNT&&cache.bytes<=CLOSED_CACHE_BYTES);}assert_eq!(f.cache.lock().unwrap().entries.len(),1);assert_eq!(f.parses(),33);}
#[test]fn oversized_verified_rows_fall_back_to_uncached_original_verification(){let mut f=F::new();for i in 1..=5{f.closed(i,1_800_000);}let wanted=[1,2,3,4,5];let(a,p)=f.read(&wanted).unwrap();assert!(f.cache.lock().unwrap().entries.is_empty());let(b,q)=f.read(&wanted).unwrap();assert_eq!(a,b);assert_eq!(f.parses(),2);p.validate().unwrap();q.validate().unwrap();assert_eq!(f.cache.lock().unwrap().bytes,0);}
/// Root supplies ONLY a separately copied, immutable original dispatch prefix.
/// This test never opens a Session/account client or the production bank/log.
#[test]#[ignore]fn offline_copied_original_dispatch_cold_warm_benchmark(){
 let path=PathBuf::from(std::env::var("MOLOCH_CLOSED_CACHE_OFFLINE_LOG").expect("explicit private copied prefix required"));assert!(path.is_absolute()&&path.components().any(|c|c.as_os_str()=="offline-closure-cache"));assert!(!path.to_string_lossy().contains("/shared/live-production-v1/"));
 let raw=fs::read(&path).unwrap();assert_eq!(bytes_sha(&raw),std::env::var("MOLOCH_CLOSED_CACHE_EXPECTED_SHA256").unwrap());assert_eq!(raw.len() as u64,std::env::var("MOLOCH_CLOSED_CACHE_EXPECTED_BYTES").unwrap().parse::<u64>().unwrap());drop(raw);
 let log=DispatchLog::open(&path).unwrap();let identity=identity(&File::open(&path).unwrap()).unwrap();let cache=Mutex::new(ClosedRowsCache::default());let wanted=[10790,10795,10828].into();let head=log.descriptor_identity().unwrap();
 let start=std::time::Instant::now();let(cold,p)=original_closed_rows(&cache,&path,&identity,&log,&wanted).unwrap();let cold_ms=start.elapsed().as_secs_f64()*1000.0;
 let start=std::time::Instant::now();let(warm,q)=original_closed_rows(&cache,&path,&identity,&log,&wanted).unwrap();let warm_ms=start.elapsed().as_secs_f64()*1000.0;
 assert_eq!(cold,warm);assert_eq!(cache.lock().unwrap().parses,1);assert_eq!(head,log.descriptor_identity().unwrap());p.validate().unwrap();q.validate().unwrap();
 println!("{}",json!({"originalBytes":head["bytes"],"originalSequence":head["sequence"],"wanted":wanted,"rowsSha256":digest(&cold).unwrap(),"fullParsePasses":1,"coldMs":cold_ms,"warmMs":warm_ms,"warmFullFileHashRequired":true,"financialAuthority":false}));
}
